def lps(s):
    # Initialize a 2D list to store the lengths of longest palindromic subsequences
    dp = [[0] * (len(s) + 1) for _ in range(len(s) + 1)]

    # Fill the dp table
    for i in range(1, len(s) + 1):
        for j in range(1, len(s) + 1):
            if s[i - 1] == s[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

